  final n = transformedString.length;

  // Step 2: Create initial matrix with empty strings
  final matrix = List<String>.filled(n, '');

  // Step 3: Reconstruct matrix columns
  for (var col = 0; col < n; col++) {
    // Append corresponding character to each row
    for (var row = 0; row < n; row++) {
      matrix[row] = matrix[row] + transformedString[row];
