List quickSort(List list) {
  // Base case: return if length <= 1
  if (list.length <= 1) {
    return list;
  }

  // Partitioning
  final pivot = list[0];
  final left = [];
  final equal = [];
  final right = [];

  // Distribute elements into partitions
  for (final element in list) {
