String formatWithCommas(dynamic input) {
  // Step 1: Convert input to string
  final String digits = input is String ? input : input.toString();
  final int n = digits.length;

  if (n <= 1) return digits;  // No formatting needed

  // Step 2: Calculate initial comma position
  int commaPos = ((n - 1) % 3) + 1;
  final buffer = StringBuffer();

  // Step 3: Iterate and format
  for (int i = 0; i < n; i++) {
    buffer.write(digits[i]);
    // Step 4: Insert comma if at separator position
    if (i == commaPos - 1 && i < n - 1) {
      buffer.write(',');
      commaPos += 3;  // Next comma position
    }
  }

  // Step 5: Return formatted string
  return buffer.toString();
}
```

