func game() {
    // Initialize game state
    wumpus = Int.random(in: 2...21)
    repeat { bat1 = Int.random(in: 2...21) } 
    while bat1 == wumpus
    repeat { bat2 = Int.random(in: 2...21) } 
    while bat2 == bat1 || bat2 == wumpus
    repeat { pit1 = Int.random(in: 2...21) } 
    while pit1 == bat1 || pit1 == bat2
    repeat { pit2 = Int.random(in: 2...21) } 
