func isValid960Position(_ position: String) -> Bool {
    var rookCount = 0
    var firstBishopParity: Int? = nil  // Stores parity (0=even, 1=odd) of first bishop

    for (index, piece) in position.enumerated() {
        switch piece {
        case "K":  // King validation
            // King must appear after exactly one rook
            if rookCount != 1 {
                return false
            }

        case "R":  // Rook counting
            rookCount += 1

        case "B":  // Bishop validation
            let currentParity = index & 1  // 0 for even index, 1 for odd

            if let existingParity = firstBishopParity {
                // Second bishop found - must have opposite parity
                if existingParity == currentParity {
                    return false
                }
            } else {
                // First bishop encountered - store its parity
                firstBishopParity = currentParity
            }

        default:  // Other pieces (queens/knights) don't affect validation
            break
        }
    }

    return true
}
