func jaroWinklerMatch(_ s1: String, _ s2: String) -> Double {
    let len1 = s1.count
    let len2 = s2.count

    // Handle edge cases
    if len1 == 0 && len2 == 0 {
        return 1.0
    }
    if len1 == 0 || len2 == 0 {
        return 0.0
    }

    // Calculate matching threshold
    let threshold = max(len1, len2) / 2 - 1
    var matches1 = [Bool](repeating: false, count: len1)
    var matches2 = [Bool](repeating: false, count: len2)

    let s1Chars = Array(s1)
    let s2Chars = Array(s2)

    // Find matching characters within threshold
    var matches = 0
    for i in 0..<len1 {
        let low = max(0, i - threshold)
        let high = min(len2 - 1, i + threshold)
        for j in low...high where !matches2[j] && s1Chars[i] == s2Chars[j] {
            matches1[i] = true
            matches2[j] = true
            matches += 1
            break
        }
    }

    // No matches found
    if matches == 0 {
        return 0.0
    }

    // Count transpositions
    var transpositions = 0
    var k = 0
    for i in 0..<len1 where matches1[i] {
        while k < len2 && !matches2[k] {
            k += 1
        }
        if k < len2 && s1Chars[i] != s2Chars[k] {
            transpositions += 1
        }
        k += 1
    }

    // Calculate Jaro similarity
    let m = Double(matches)
    let t = Double(transpositions)
    let len1d = Double(len1)
    let len2d = Double(len2)

    return (m/len1d + m/len2d + (m - t/2)/m) / 3.0
}
```

### Key Implementation Details:
1. **Edge Case Handling**:
   - Returns 1.0 when both strings are empty
   - Returns 0.0 when one string is empty
   - Handles single-character strings through the main algorithm

2. **Matching Process**:
   - Uses a sliding window approach based on `threshold`
   - Marks matches in two boolean arrays to track character matches
   - Converts strings to character arrays for efficient indexing

3. **Transposition Counting**:
   - Compares matched characters in order
   - Counts mismatched pairs where characters match but positions differ
   - Uses half the transposition count in final calculation

4. **Jaro Formula**:
   - Computes three components:
     1. Ratio of matches to first string length
     2. Ratio of matches to second string length
     3. Ratio of matches minus half transpositions to total matches
   - Averages the three components and divides by 3

