extension Collection where Element == Point {
    func closestPairBruteForce() -> (distance: Double, point1: Element, point2: Element)? {
        let n = self.count
        precondition(n >= 0, "Count cannot be negative")

        // Handle insufficient points
        guard n >= 2 else { return nil }

        // Special case: Exactly 2 points
        if n == 2 {
            let p1 = self[startIndex]
            let p2 = self[index(startIndex, offsetBy: 1)]
            return (p1.distance(to: p2), p1, p2)
        }

        var minDistance = Double.greatestFiniteMagnitude
        var bestPair: (Element, Element)?

        // Compare all unique pairs (i, j) where j > i
        for i in 0..<(n - 1) {
            let indexI = index(startIndex, offsetBy: i)
            for j in (i + 1)..<n {
                let indexJ = index(startIndex, offsetBy: j)
                let pI = self[indexI]
                let pJ = self[indexJ]
                let distance = pI.distance(to: pJ)

                // Update best pair if closer
                if distance < minDistance {
                    minDistance = distance
                    bestPair = (pI, pJ)
                }
            }
        }

        // Unwrap guaranteed result (n >= 2 ensures non-nil)
