extension Array where Element: Comparable {
    func cocktailSorted() -> [Element] {
        // Handle trivial cases (0 or 1 element)
        guard count > 1 else { return self }

        var array = self
        var swapped = true

        while swapped {
            swapped = false

            // Forward pass (left to right)
            for i in 0..<array.count - 1 {
                if array[i] > array[i + 1] {
                    array.swapAt(i, i + 1)
                    swapped = true
                }
            }

            // Exit if no swaps occurred
            guard swapped else { break }
            swapped = false

            // Backward pass (right to left)
            for i in stride(from: array.count - 2, through: 0, by: -1) {
                if array[i] > array[i + 1] {
                    array.swapAt(i, i + 1)
                    swapped = true
                }
            }
        }

        return array
    }
}
