func mianChowla(n: Int) -> [Int] {
    precondition(n >= 1, "n must be at least 1")
    var sequence = [1]
    guard n > 1 else { return sequence }

    var seenSums: Set<Int> = [2]  // 1+1=2

    for _ in 1..<n {
        var candidate = sequence.last! + 1
        var found = false

        while !found {
            found = true
            // Check all pairwise sums with existing terms
            for term in sequence {
                let sum = candidate + term
                if seenSums.contains(sum) {
                    found = false
                    break
                }
            }

            if found {
                // Add new term to sequence
                sequence.append(candidate)
                // Register all new pairwise sums
                for term in sequence {
                    seenSums.insert(candidate + term)
                }
            } else {
                candidate += 1
            }
        }
    }
    return sequence
}
```

