func commonPrefix<T: Equatable>(_ a: [T], _ b: [T]) -> [T] {
    let minLength = min(a.count, b.count)

    // Iterate from minLength-1 down to 0 to find the longest match
    for i in (0..<minLength).reversed() {
        let prefixOfA = a.prefix(i)
        if b.starts(with: prefixOfA) {
            return Array(prefixOfA)
        }
    }

    // Return empty array if no common prefix found
    return []
}
```

