```swift
func vampire<T: BinaryInteger>(n: T) -> [(T, T)] {
    let nStr = String(n)
    let sortedNStr = String(nStr.sorted())

    let digits = nStr.count
    guard digits % 2 == 0 else { return [] }
    let halfDigits = digits / 2

    // Calculate lower bound (smallest halfDigits-digit number)
    var lowerBound: T = 1
    for _ in 1..<halfDigits {
        lowerBound *= 10
    }

    // Calculate upper bound (integer square root of n)
    let upperBound = T(Double(n).squareRoot().rounded(.down))

    var results: [(T, T)] = []
    var i = lowerBound

    while i <= upperBound {
        guard n % i == 0 else { 
            i += 1
            continue
        }

        let j = n / i
        let iStr = String(i)
        let jStr = String(j)

        // Verify both factors have exactly halfDigits digits
        guard iStr.count == halfDigits, jStr.count == halfDigits else {
            i += 1
            continue
        }

        // Skip pairs with trailing zeros in both factors
        guard !(iStr.last! == "0" && jStr.last! == "0") else {
            i += 1
            continue
        }

        // Check digit permutation condition
        if String((iStr + jStr).sorted()) == sortedNStr {
            results.append((i, j))
        }

        i += 1
    }

    return results
}
```

