extension Int {
    func isPrime() -> Bool {
        // Numbers less than 2 are not prime
        guard self >= 2 else { return false }

        // 2 is prime
        if self == 2 { return true }

        // Even numbers greater than 2 are not prime
        if self % 2 == 0 { return false }

        // Calculate integer square root as the upper bound
        let limit = Int(Double(self).squareRoot())

        // Check divisibility by odd numbers from 3 to limit
        return !stride(from: 3, through: limit, by: 2).contains { divisor in
            self % divisor == 0
        }
    }
}
```

