```swift
struct Point {
    var x: Double
    var y: Double
}

struct Line {
    var p1: Point
    var p2: Point

    var slope: Double {
        if p1.x == p2.x { 
            return Double.nan
        }
        return (p2.y - p1.y) / (p2.x - p1.x)
    }

    func intersection(with other: Line) -> Point? {
        let m1 = self.slope
        let m2 = other.slope

        // Case 1: Parallel lines (same non-NaN slope)
        if m1 == m2 && !m1.isNaN && !m2.isNaN {
            return nil
        }

        // Case 2: Self is vertical, other is not
        if m1.isNaN && !m2.isNaN {
            let x = self.p1.x
            let y = m2 * (x - other.p1.x) + other.p1.y
            return Point(x: x, y: y)
        }

        // Case 3: Other is vertical, self is not
        if m2.isNaN && !m1.isNaN {
            let x = other.p1.x
            let y = m1 * (x - self.p1.x) + self.p1.y
            return Point(x: x, y: y)
        }

        // Case 4: Both vertical (always parallel)
        if m1.isNaN && m2.isNaN {
            return nil
        }

        // Case 5: General non-parallel case
        let numerator = m1 * other.p1.x - m2 * self.p1.x + self.p1.y - other.p1.y
        let denominator = m1 - m2
        let x = numerator / denominator
        let y = m2 * (x - self.p1.x) + self.p1.y
        return Point(x: x, y: y)
    }
}
```

Key implementation details:
1. **Slope Handling**: Uses `Double.nan` for vertical lines (infinite slope)
2. **Parallel Check**: Returns `nil` for equal non-NaN slopes or both vertical
3. **Vertical Line Special Cases**: Uses the vertical line's x-coordinate directly
4. **General Intersection**: Implements the formula:
   ```
   x = (m1·xₒ - m2·xₛ + yₛ - yₒ) / (m1 - m2)
   y = m2·(x - xₛ) + yₛ
   ```
   Where (xₛ,yₛ) is self.p1 and (xₒ,yₒ) is other.p1

