func duration(_ seconds: Int) -> String {
    if seconds < 0 {
        return "0 seconds"
    }

    let timeUnits = [
        (604800, "week"),    // Seconds in a week
        (86400, "day"),      // Seconds in a day
        (3600, "hour"),      // Seconds in an hour
        (60, "minute")       // Seconds in a minute
    ]

    var remaining = seconds
    var result = ""

    // Process larger time units first
    for (value, unit) in timeUnits {
        if remaining >= value {
            let count = remaining / value
            remaining %= value
            result += "\(count) \(unit), "
        }
    }

    // Handle remaining seconds
    if remaining > 0 {
        result += "\(remaining) second"
    } else {
        if !result.isEmpty {
            // Remove trailing comma+space if no seconds follow
            result.removeLast(2)
        } else {
            // Handle 0 seconds case
            result = "0 seconds"
        }
    }

    return result
}
```

