func maxSubseq(sequence: [Int]) -> (Int, Int, Int) {
    var bestSum = 0
    var currentSum = 0
    var currentStart = 0
    var bestStart = 0
    var bestEnd = -1  // -1 indicates no valid segment found

    for (index, value) in sequence.enumerated() {
        // Add current value to running sum
        currentSum += value

        if currentSum < 0 {
            // Reset segment if sum becomes negative
            currentStart = index + 1
            currentSum = 0
        } else if currentSum > bestSum {
            // Found new best segment
            bestSum = currentSum
            bestStart = currentStart
            bestEnd = index
        }
    }

    // Handle invalid segment (all negatives or empty)
    if bestEnd < bestStart {
        return (0, 0, 0)
    }

    // Convert end index to exclusive form
    return (bestStart, bestEnd + 1, bestSum)
}
```

