func isPrime(number: Int) -> Bool {
    // Numbers less than 2 are not prime
    if number < 2 {
        return false
    }

    // Check divisibility by 2
    if number % 2 == 0 {
        return number == 2  // Only even prime
    }

    // Check divisibility by 3
    if number % 3 == 0 {
        return number == 3  // Only divisible by 3 if it's 3 itself
    }

    // Check divisibility by 5
    if number % 5 == 0 {
        return number == 5  // Only divisible by 5 if it's 5 itself
    }

    var current = 7
    // Step pattern for efficient prime checking (avoids multiples of 2,3,5)
    let pattern = [4, 2, 4, 2, 4, 6, 2, 6]
    var patternIterator = pattern.makeIterator()

    while true {
        // Get next step from pattern (reset if exhausted)
        guard var increment = patternIterator.next() else {
            patternIterator = pattern.makeIterator()
            increment = patternIterator.next()!  // Safe since pattern is non-empty
        }

        // Check for multiplication overflow
        let (square, overflowMul) = current.multipliedReportingOverflow(by: current)
        guard !overflowMul else {
            fatalError("Integer overflow in multiplication")
        }

        // Exit condition: current^2 > number
        if square > number {
            return true  // No divisors found
        }

        // Prevent division by zero
        guard current != 0 else {
            fatalError("Division by zero attempted")
        }

        // Check divisibility by current value
        if number % current == 0 {
            return false  // Found a divisor
        }

        // Update current with overflow check
        let (newCurrent, overflowAdd) = current.addingReportingOverflow(increment)
        guard !overflowAdd else {
            fatalError("Integer overflow in addition")
        }
        current = newCurrent
    }
}
```

