func nextPrimeDigitNumber(number: Int) -> Int {
    if number == 0 {
        return 2
    }

    let lastDigit = number % 10

    if lastDigit == 2 {
        return number + 1
    } else if lastDigit == 3 || lastDigit == 5 {
        return number + 2
    } else {
        let prefix = nextPrimeDigitNumber(number: number / 10)
        return prefix * 10 + 2
    }
}
