func trialPrimes(_ n: Int) {
    guard n >= 3 else { return }  // Handle cases where n < 3

    var candidate = 3  // Start checking from first odd number

    while candidate <= n {
        var isPrime = true

        // Check divisibility against existing primes
        for prime in primes {
            // Early exit if prime^2 exceeds candidate
            if prime * prime > candidate {
                break
            }

            // Found a divisor → composite number
            if candidate % prime == 0 {
                isPrime = false
                break
            }
        }

        // Append prime and proceed if no divisors found
        if isPrime {
            primes.append(candidate)
