struct Perlin {
    // Permutation table (512 entries for wrap-around)
    private static let p: [Int] = {
        var perm = [Int]()
        // This should be populated with 0-255 repeated twice
        // For brevity, we'll initialize with dummy values
        return Array(repeating: 0, count: 512)
    }()

    public static func noise(x: Double, y: Double, z: Double) -> Double {
        // Input validation (0.0 ≤ x,y,z ≤ 1.0)
        assert(x.isFinite && x >= 0.0 && x <= 1.0, "x out of bounds [0,1]")
        assert(y.isFinite && y >= 0.0 && y <= 1.0, "y out of bounds [0,1]")
        assert(z.isFinite && z >= 0.0 && z <= 1.0, "z out of bounds [0,1]")

        let X = Int(x) & 0xFF  // Integer part of X
        let Y = Int(y) & 0xFF  // Integer part of Y
        let Z = Int(z) & 0xFF  // Integer part of Z

        let x = x - floor(x)   // Fractional part of X
        let y = y - floor(y)   // Fractional part of Y
        let z = z - floor(z)   // Fractional part of Z

        let u = fade(x)        // Fade curve for X
        let v = fade(y)        // Fade curve for Y
        let w = fade(z)        // Fade curve for Z

        // Hash coordinates for cube corners
        let A  = p[X] + Y
        let AA = p[A] + Z
        let AB = p[A + 1] + Z
        let B  = p[X + 1] + Y
        let BA = p[B] + Z
        let BB = p[B + 1] + Z

        // Bottom layer gradients (Z fixed)
        let g0 = grad(h: p[AA], x: x, y: y, z: z)
        let g1 = grad(h: p[BA], x: x - 1, y: y, z: z)
        let g2 = grad(h: p[AB], x: x, y: y - 1, z: z)
        let g3 = grad(h: p[BB], x: x - 1, y: y - 1, z: z)

        // Top layer gradients (Z+1)
        let g4 = grad(h: p[AA + 1], x: x, y: y, z: z - 1)
        let g5 = grad(h: p[BA + 1], x: x - 1, y: y, z: z - 1)
        let g6 = grad(h: p[AB + 1], x: x, y: y - 1, z: z - 1)
        let g7 = grad(h: p[BB + 1], x: x - 1, y: y - 1, z: z - 1)

        // Trilinear interpolation
        let bottomFront = lerp(a: g0, b: g1, t: u)  // X-interp bottom front
        let bottomBack  = lerp(a: g2, b: g3, t: u)  // X-interp bottom back
        let bottom = lerp(a: bottomFront, b: bottomBack, t: v)  // Y-interp bottom

        let topFront = lerp(a: g4, b: g5, t: u)     // X-interp top front
        let topBack  = lerp(a: g6, b: g7, t: u)     // X-interp top back
        let top = lerp(a: topFront, b: topBack, t: v)        // Y-interp top

        return lerp(a: bottom, b: top, t: w)  // Final Z-interpolation
    }

    // MARK: - Helper Functions
    private static func fade(_ t: Double) -> Double {
        t * t * t * (t * (t * 6 - 15) + 10)  // 6t⁵ - 15t⁴ + 10t³
    }

    private static func lerp(a: Double, b: Double, t: Double) -> Double {
        a + t * (b - a)  // Linear interpolation
    }

    private static func grad(h: Int, x: Double, y: Double, z: Double) -> Double {
        let h = h & 15  // Use low 4 bits for gradient selection
        let u = h < 8 ? x : y
        let v = h < 4 ? y : (h == 12 || h == 14) ? x : z
        return ((h & 1) == 0 ? u : -u) + ((h & 2) == 0 ? v : -v)
    }
}
```

