func networkMask(_ bits: Int) -> UInt32 {
    // Step 1: Clamp input to [-64, 64] range
    let clampedBits: Int
    if bits < -64 {
        clampedBits = -64
    } else if bits > 64 {
        clampedBits = 64
    } else {
        clampedBits = bits
    }

    // Step 2: Compute base mask
    let mask64: UInt64
    if clampedBits < 0 {
        mask64 = 0xFFFF_FFFF_FFFF_FFFF
    } else if clampedBits < 64 {
        mask64 = 1 << clampedBits
    } else {
        mask64 = 0
    }

    // Step 3: Compute temp value (mask64 - 1) with overflow check
    let temp = mask64 &- 1
    let tempSigned = Int64(bitPattern: temp)

    // Step 4: Validate temp value (assembly assertions)
    guard tempSigned >= 0 else {
        preconditionFailure("Negative mask value")
    }
    guard tempSigned <= 0xFFFF_FFFF else {
        preconditionFailure("Mask value exceeds 32-bit range")
    }

    // Step 5: Extract 32-bit mask
    let mask32 = UInt32(truncatingIfNeeded: temp)
    let shift = 32 - bits  // Use original bits, not clamped

    // Step 6: Clamp shift to [-32, 32]
    let clampedShift: Int
    if shift < -32 {
        clampedShift = -32
    } else if shift > 32 {
        clampedShift = 32
    } else {
        clampedShift = shift
    }

    // Step 7: Apply shift operation
    switch clampedShift {
    case ..<0:
        let shiftAmount = UInt32(-clampedShift) & 31
        return mask32 >> shiftAmount
    case 0..<32:
        let shiftAmount = UInt32(clampedShift) & 31
        return mask32 << shiftAmount
    default:  // ±32 or out-of-range
        return 0
    }
}
```

