func primeSieve(limit: Int) -> [Bool] {
    guard limit > 0 else { return [] }
    var sieve = [Bool](repeating: true, count: limit)

    // Handle base cases
    if limit > 0 { sieve[0] = false }
    if limit > 1 { sieve[1] = false }

    // Special case: Mark even numbers (except 2)
    if limit > 4 {
        for i in stride(from: 4, to: limit, by: 2) {
            sieve[i] = false
        }
    }

    var prime = 3
    while prime * prime <= limit {
        if sieve[prime] {
            var multiple = prime * prime
            while multiple < limit {
                sieve[multiple] = false
                multiple += 2 * prime  // Skip even multiples
            }
        }
        prime += 2  // Check next odd number
    }

    return sieve
}
