class KnightsTour {
    private var board: [[Int]]
    private let size: Int
    private var currentStep: Int = 0

    init(size: Int) {
        self.size = size
        self.board = Array(repeating: Array(repeating: 0, count: size), count: size)
    }

    private func reset() {
        for i in 0..<size {
            for j in 0..<size {
                board[i][j] = 0
            }
        }
        currentStep = 0
    }

    private func isValid(point: CPoint) -> Bool {
        return point.x >= 0 && point.x < size && point.y >= 0 && point.y < size
    }

    private static let knightMoves = [
        (2, 1), (1, 2), (-1, 2), (-2, 1),
        (-2, -1), (-1, -2), (1, -2), (2, -1)
    ]

    private func nextMovesCount(at point: CPoint) -> Int {
        return Self.knightMoves.lazy
            .map { CPoint(x: point.x + $0.0, y: point.y + $0.1) }
            .filter { isValid(point: $0) && board[$0.x][$0.y] == 0 }
            .count
    }

    func tour(startingAt point: CPoint) -> Bool {
        reset()
        guard isValid(point: point) else { return false }

        let totalSquares = size * size
        currentStep = 1
        board[point.x][point.y] = currentStep
        var current = point

        while currentStep < totalSquares {
            // Generate valid next moves using lazy evaluation
            let nextMoves = Self.knightMoves.lazy
                .map { CPoint(x: current.x + $0.0, y: current.y + $0.1) }
                .filter { isValid(point: $0) && board[$0.x][$0.y] == 0 }

