import Foundation

func lastFridays(of year: Int) -> [Date] {
    let calendar = Calendar.current
    var dates: [Date] = []

    for month in 1...12 {
        // Create components for the 13th of the month (safe mid-month date)
        var components = DateComponents()
        components.calendar = calendar
        components.year = year
        components.month = month
        components.day = 13

        // Get date and check if it's already a Friday
        guard let date = calendar.date(from: components) else { continue }
        let weekday = calendar.component(.weekday, from: date)

        if weekday == 6 {  // 6 = Friday (1=Sun, 7=Sat)
            dates.append(date)
        } else {
            // Calculate ordinal position (n-th Friday in month)
            guard let ordinal = calendar.ordinality(
                of: .weekdayOrdinal, 
                in: .month, 
                for: date
