struct VanEckSequence: Sequence, IteratorProtocol {
    private var index = 0
    private var lastTerm = 0
    private var lastPos = Dictionary<Int, Int>()
    mutating func next() -> Int? {
        let result = lastTerm
        var nextTerm = 0
        if let v = lastPos[lastTerm] {
