extension Float {
    func root<A: FloatingPoint>(
        n: Int, 
        epsilon: A
    ) -> A where A: ExpressibleByFloatLiteral {
        // Convert base value to generic floating-point type
        let base = A(self)

        // Handle special cases
        guard n != 1 else { return base }
        guard n >= 1 else { return .nan }

        // Constants for calculation
        let n_A = A(n)
        let n_minus_1 = A(n - 1)
        var x0 = A(1.0)  // Initial guess
        var x1: A

        // Newton-Raphson iteration
        repeat {
            let x_power = pow(x0, n_minus_1)
            x1 = (n_minus_1 * x0 + base / x_power) / n_A

            // Check convergence
            if abs(x1 - x0) <= epsilon { break }

            x0 = x1
        } while true

        return x1
    }

    // Helper for integer exponentiation
    private func pow<A: FloatingPoint>(_ base: A, _ exponent: A) -> A {
        var result = A(1.0)
        let intExp = Int(exponent)

        for _ in 0..<intExp {
            result = result * base
        }
        return result
    }
}
