```swift
struct KnapsackItem {
    let weight: Int
    let value: Int
}

func knapsack(items: [KnapsackItem], limit: Int) -> [KnapsackItem] {
    guard !items.isEmpty else { return [] }

    let n = items.count
    // Create DP table: dp[i][w] = max value using first i items with capacity w
    var dp = Array(
        repeating: Array(repeating: 0, count: limit + 1),
        count: n + 1
    )

    // Build DP table
    for i in 1...n {
        let item = items[i-1]
        for w in 0...limit {
            if item.weight > w {
                dp[i][w] = dp[i-1][w]
            } else {
                dp[i][w] = max(
                    dp[i-1][w],
                    dp[i-1][w - item.weight] + item.value
                )
            }
        }
    }

    // Backtrack to find selected items
    var selectedItems: [KnapsackItem] = []
    var remainingCapacity = limit

    for i in stride(from: n, to: 0, by: -1) {
        if dp[i][remainingCapacity] != dp[i-1][remainingCapacity] {
            let item = items[i-1]
            selectedItems.append(item)
            remainingCapacity -= item.weight
        }
    }

    return selectedItems
}
```

### Key Implementation Details:
1. **DP Table Initialization**:
   - Creates a 2D array `(n+1) x (limit+1)` initialized to 0
   - Rows represent items, columns represent capacities

2. **Table Population**:
   - Iterates through each item and capacity
   - For each cell `[i][w]`:
     - If item doesn't fit (`weight > w`): carry forward previous best
     - If item fits: take max of excluding or including the item

3. **Solution Reconstruction**:
   - Starts from bottom-right corner of DP table
   - Moves upward comparing current cell with cell directly above
   - When values differ, item is added to solution and capacity reduced

### Optimization Notes:
- Space complexity: O(n*limit)
- Time complexity: O(n*limit)
- Backtracking efficiently reconstructs solution in O(n) time
- Handles edge cases (empty input) via guard statement

