public func gcd(with other: Self) -> Self {
  var gcd = self
  var b = other

  while b != 0 {
    (gcd, b) = (b, gcd % b)
  }

  return gcd
}

public func lcm(with other: Self) -> Self {
  let g = gcd(with: other)

  return self / g * other
}

