func knapsack(items: [KnapsackItem], limit: Int) -> [KnapsackItem] {
    let n = items.count
    // Create DP table with dimensions (n+1) x (limit+1)
    var dp = Array(repeating: Array(repeating: 0, count: limit + 1), count: n + 1)

    // Build DP table
    for i in 1...n {
        let current = items[i-1]
        for w in 0...limit {
            if current.weight <= w {
                dp[i][w] = max(
                    dp[i-1][w], 
                    dp[i-1][w - current.weight] + current.value
                )
            } else {
                dp[i][w] = dp[i-1][w]
            }
        }
    }

    // Backtrack to find selected items
    var selected: [KnapsackItem] = []
    var remaining = limit
    var i = n

    while i > 0 && remaining > 0 {
        if dp[i][remaining] != dp[i-1][remaining] {
            let item = items[i-1]
            selected.append(item)
            remaining -= item.weight
        }
        i -= 1
    }

    return selected
}
```

