func jaroWinklerDistance(string1: String, string2: String) -> Double {
    // Convert strings to character arrays
    let chars1 = Array(string1)
    let chars2 = Array(string2)
    let len1 = chars1.count
    let len2 = chars2.count

    // Handle empty string cases
    if len1 == 0 && len2 == 0 {
        return 0.0
    }

    // Swap strings if needed so first is longer
    let (a, b, aLen, bLen): ([Character], [Character], Int, Int) = {
        if len1 < len2 {
            return (chars2, chars1, len2, len1)
        }
        return (chars1, chars2, len1, len2)
    }()

    if bLen == 0 {
        return aLen > 0 ? 1.0 : 0.0
    }

    // Calculate matching window size
    let window = max(1, aLen / 2) - 1

    // Initialize match tracking
    var bMatches = [Bool](repeating: false, count: bLen)
    var aCommon = [Character]()
    aCommon.reserveCapacity(aLen)

    // Find matching characters
    for (i, aChar) in a.enumerated() {
        let start = max(0, i - window)
        let end = min(bLen - 1, i + window)

        for j in start...end where !bMatches[j] && aChar == b[j] {
            bMatches[j] = true
            aCommon.append(aChar)
            break
        }
    }

    let matches = aCommon.count
    guard matches > 0 else { return 1.0 }

    // Get matching characters from second string
    var bCommon = [Character]()
    for (j, matched) in bMatches.enumerated() where matched {
        bCommon.append(b[j])
    }

    // Count transpositions
    var transpositions = 0
    for k in 0..<matches where aCommon[k] != bCommon[k] {
        transpositions += 1
    }

    // Calculate Jaro similarity
    let m = Double(matches)
    let t = Double(transpositions) / 2.0
    let jaro = (m / Double(aLen) + m / Double(bLen) + (m - t) / m) / 3.0

    // Calculate prefix length (max 4)
    var prefixLength = 0
    let maxPrefix = min(4, bLen)
    for i in 0..<maxPrefix where a[i] == b[i] {
        prefixLength += 1
    }

    // Calculate Jaro-Winkler similarity
    let winkler = jaro + Double(prefixLength) * 0.1 * (1.0 - jaro)

    // Return distance
    return 1.0 - winkler
}
```

