extension String {
    func commatize(start: Int, period: Int, separator: String) -> String {
        // Return original if separator is empty or invalid period
        guard !separator.isEmpty, period > 0 else { return self }

        // Find decimal point position
        let decimalRange = range(
            of: "\\.",
            options: .regularExpression,
            range: index(startIndex, offsetBy: start)..<endIndex
        )

        // Split into integer/fractional parts
        let integerEnd = decimalRange?.lowerBound ?? endIndex
        let integerPart = self[index(startIndex, offsetBy: start)..<integerEnd]
        let fractionalPart = decimalRange.map { self[$0.lowerBound..<endIndex] }

        // Process integer part in reverse
        let reversedInteger = String(integerPart.reversed())
        var formattedReversed = ""
        var index = reversedInteger.startIndex

        while index < reversedInteger.endIndex {
            let end = reversedInteger.index(
                index, 
                offsetBy: period, 
                limitedBy: reversedInteger.endIndex
            ) ?? reversedInteger.endIndex

            formattedReversed += reversedInteger[index..<end]
            if end < reversedInteger.endIndex {
                formattedReversed += separator
            }
            index = end
        }

        // Recombine components
        let formattedInteger = String(formattedReversed.reversed())
        let prefix = prefix(start)

        return fractionalPart.map { 
            prefix + formattedInteger + $0 
        } ?? prefix + formattedInteger
    }
}
```

