func threeDigitsToText(n: Int) -> String {
  guard n != 0 else {
    return ""
  }

  var ret = ""

  let hundreds = n / 100
  let remainder = n % 100

  if hundreds > 0 {
    ret += "\(Int.names[hundreds]!) hundred"

    if remainder > 0 {
