func maxNugget(limit: Int) -> Int {
    guard limit > 0 else { return 0 }

    var lastNonRepresentable = 0
    var current = 0

    while current < limit {
        var isRepresentable = false

        // Try all combinations of 6a + 9b + 20c = current
        outer: for a in 0...(current / 6) {
            let sixA = 6 * a
            for b in 0...((current - sixA) / 9) {
                let nineB = 9 * b
                let partialSum = sixA + nineB
                for c in 0...((current - partialSum) / 20) {
                    if partialSum + (20 * c) == current {
                        isRepresentable = true
                        break outer
                    }
                }
            }
        }

        if isRepresentable {
            current += 1
        } else {
            lastNonRepresentable = current
            current += 1
        }
    }

    return lastNonRepresentable
}
```

