```swift
func lcs(_ s1: String, _ s2: String) -> String {
    let n = s1.count
    let m = s2.count

    // Handle empty string cases
    if n == 0 || m == 0 {
        return ""
    }

    // Convert to arrays for O(1) indexing
    let s1Chars = Array(s1)
    let s2Chars = Array(s2)

    // Initialize DP table with dimensions (n+1) x (m+1)
    var dp = Array(repeating: Array(repeating: 0, count: m+1), count: n+1)

    // Fill DP table
    for i in 1...n {
        for j in 1...m {
            if s1Chars[i-1] == s2Chars[j-1] {
                dp[i][j] = dp[i-1][j-1] + 1
            } else {
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])
            }
        }
    }

    // Backtrack to find LCS characters
    var i = n
    var j = m
    var result = [Character]()

    while i > 0 && j > 0 {
        if s1Chars[i-1] == s2Chars[j-1] {
            result.append(s1Chars[i-1])
            i -= 1
            j -= 1
        } else if dp[i-1][j] > dp[i][j-1] {
            i -= 1
        } else {
            j -= 1
        }
    }

    return String(result.reversed())
}
```

### Key Implementation Details:
1. **DP Table Initialization**: Creates a 2D array `dp` with dimensions `(n+1) x (m+1)` initialized to zeros
2. **Table Population**:
   - When characters match: `dp[i][j] = dp[i-1][j-1] + 1`
   - When characters differ: `dp[i][j] = max(dp[i-1][j], dp[i][j-1])`
3. **Backtracking**:
   - Starts from `dp[n][m]` and moves diagonally when characters match
   - Moves up/left based on DP values when characters differ
4. **Result Construction**:
   - Builds result in reverse during backtracking
   - Returns reversed string for correct sequence

