    initialValue: Double,
    stepCount: Int
) -> Double {
    // Print step count at start
    print("Step count: \(stepCount)")

    var currentValue = initialValue
    let timeRange = stride(from: startTime, through: endTime, by: stepCount)

    for timeStep in timeRange {
        // Print current value every 10 steps
        if timeStep % 10 == 0 {
            let formattedValue = String(format: numberFormat, currentValue)
            print(formattedValue, terminator: " ")
        }

        // Calculate next value using Euler's method
        let t = Double(timeStep)
        let derivative = f(t, currentValue)
        currentValue += Double(stepCount) * derivative
    }

    // Final newline after progress prints
    print()
    return currentValue
}
