func primeFactorSum(_ num: Int) -> Int {
    var sum = 0
    var n = num
    while (n & 1) == 0 {
        sum += 2
        n >>= 1
    }
    var p = 3
    while p * p <= n {
        while n % p == 0 {
            sum += p
            n /= p
        }
        p += 2
    }
    if n > 1 {
        sum += n
    }
    return sum
}

