    for sep in seps where self[i...].hasPrefix(sep) {
      if i > lastMatch {
        matches.append(self[lastMatch..<i])
      } else {
        matches.append("")
      }

      lastMatch = index(i, offsetBy: sep.count)
      matched.append((sep, (i, lastMatch)))
      i = lastMatch

      continue main
    }

    i = index(i, offsetBy: 1)
  }

  if i > lastMatch {
    matches.append(self[lastMatch..<i])
  }

  return (matches, matched)
}

