extension String {
    func multiSplit(
        on separators: [String],
        from start: Index,
        to end: Index
    ) -> (substrings: [String], matches: [(separator: String, range: Range<Index>)]) {
        guard start != end else { return ([], []) }

        var current = start
        var lastStart = start
        var substrings: [String] = []
        var matches: [(String, Range<Index>)] = []

        while current < end {
            var foundMatch = false

            for separator in separators {
                guard hasPrefix(separator, startingAt: current) else { continue }

                // Append segment before separator
                if lastStart < current {
                    let segment = self[lastStart..<current]
                    substrings.append(String(segment))
                }

                // Calculate new position after separator
                let separatorEnd = index(current, offsetBy: separator.count, limitedBy: end) ?? end
                let matchRange = current..<separatorEnd

                // Update state
                matches.append((separator, matchRange))
                lastStart = separatorEnd
                current = separatorEnd
                foundMatch = true
                break
            }

            if !foundMatch {
                current = index(after: current)
            }
        }

        // Append final segment
        if lastStart < end {
            let segment = self[lastStart..<end]
            substrings.append(String(segment))
        }

        return (substrings, matches)
    }

    private func hasPrefix(_ prefix: String, startingAt index: Index) -> Bool {
        return self[index...].starts(with: prefix)
    }
}
