func isPalin2(n: Int) -> Bool {
  var x = 0
  var n = n

  guard n & 1 != 0 else {
    return n == 0
  }

  while x < n {
    x = x << 1 | n & 1
    n >>= 1
  }

  return n == x || n == x >> 1
}

func reverse3(n: Int) -> Int {
  var x = 0
  var n = n

  while n > 0 {
    x = x * 3 + (n % 3)
    n /= 3
  }

  return x
}

