func main() {
    let max = 1_000_000
    let sqrtResult = sqrt(Double(max))

    // Validate sqrt result
    assert(!sqrtResult.isNaN && !sqrtResult.isInfinite, "sqrt returned NaN or infinity")
    assert(sqrtResult > 0.0, "sqrt returned non-positive")
    assert(sqrtResult < 1000.0 + 1, "sqrt result out of bounds")

