    for i in 2...maxroot {
        guard isprime[i] else { continue }

        // Calculate starting point (i*i) with overflow check
        let (square, overflow) = i.multipliedReportingOverflow(by: i)
        guard !overflow else { fatalError("Multiplication overflow") }

        // Skip if starting point exceeds max
        guard square <= max else { continue }

        // Mark multiples of i as non-prime
        for j in stride(from: square, through: max, by: i) {
            isprime[j] = false
