    guard limit >= 3 else { return }

    // Calculate odd numbers count from 3 to limit
    let oddCount = (limit - 3) / 2 + 1
    let requiredBufferSize = Int((oddCount + 7) / 8)
    assert(buffer.count >= requiredBufferSize, "Insufficient buffer size")

    var primeIterator = primes.makeIterator()
    while let primeBatch = primeIterator.next() {
        for primeVal in primeBatch {
            let p = UInt64(primeVal)
            let start = p * p
            guard start < limit else { break }

            // Calculate initial index and step size
            var index = (start - 3) / 2
            let step = p

