                    wordPtr.pointee |= UInt32(bitMask)
                } else {
                    buffer[byteIndex] |= bitMask
                }

                // Next composite with overflow check
                let nextIndex = index + step
                guard nextIndex > index else { break } // Overflow check
                index = nextIndex
            }
        }
    }
}
```

