    case invalidSize
    case oddSizeRequired
}

class MagicSquare {
    let size: Int
    var grid: [[Int]]

    init(size: Int) {
        self.size = size
        self.grid = Array(repeating: Array(repeating: 0, count: size), count: size)
    }

    func createOdd() throws -> MagicSquare {
        // Validate size is odd and ≥ 1
        guard size >= 1 else {
            throw MagicSquareError.invalidSize
        }
        guard size % 2 != 0 else {
            throw MagicSquareError.oddSizeRequired
        }

        // Initialize position variables
        var row = 0
        var col = size / 2
        let totalNumbers = size * size

        // Generate magic square using Siamese method
        for num in 1...totalNumbers {
            // Place current number
            grid[row][col] = num

            // Calculate next position (move up-right)
            let nextRow = (row - 1 + size) % size
            let nextCol = (col + 1) % size

            // If next cell is occupied, move down instead
            if grid[nextRow][nextCol] != 0 {
                row = (row + 1) % size
            } else {
                row = nextRow
                col = nextCol
            }
        }

        return self
    }
}
