    let grads = angle * 200 / .pi
    return (grads.truncatingRemainder(dividingBy: 400) + (grads < 0 ? 400 : 0)
}

func normalizeToMil(_ angle: Double) -> Double {
    let mils = angle * 3200 / .pi
    return (mils.truncatingRemainder(dividingBy: 6400) + (mils < 0 ? 6400 : 0)
}

func normalizeToRad(_ angle: Double) -> Double {
    let radians = angle.truncatingRemainder(dividingBy: 2 * .pi)
    return radians < 0 ? radians + 2 * .pi : radians
}

