static func isAlmostEqual(to other: Self, tolerance: Self) -> Bool {
    // Ensure tolerance is non-negative
    guard tolerance >= 0 else {
        preconditionFailure("tolerance must be non-negative")
    }

    // Handle finite values
    if self.isFinite && other.isFinite {
        // Compute scale = max(|self|, |other|, .leastNormalMagnitude)
        let scale = max(abs(self), abs(other), Self.leastNormalMagnitude)

        // Calculate absolute tolerance threshold
        let absTolerance = tolerance * scale * Self.ulpOfOne

        // Compare absolute difference to tolerance
        return abs(self - other) <= absTolerance
    }
    // Handle non-finite values (inf/nan)
    else {
        return rescaledAlmostEqual(to: other, tolerance: tolerance)
    }
}
```

