extension FloatingPoint {
    static func rescaledAlmostEqual(_ a: Self, to b: Self, tolerance: Self) -> Bool {
        // Handle NaN cases
        if a.isNaN || b.isNaN {
            return false
        }

        // Handle infinity cases
        if a.isInfinite || b.isInfinite {
            guard a.isInfinite && b.isInfinite else {
                return false
            }
            return a.sign == b.sign
