	    diagr[0] = (bit0>>1|bit1)>>1

	    var posib: Int = ~(cols[0] | diagl[0] | diagr[0])

	    while (d >= 0) {
		while(posib != 0) {
		    let bit: Int = posib & -posib
		    let ncols: Int = cols[d] | bit
		    let ndiagl: Int = (diagl[d] | bit) << 1;
		    let ndiagr: Int = (diagr[d] | bit) >> 1;
		    let nposib: Int = ~(ncols | ndiagl | ndiagr);
