func nq(n: Int) -> Int {
    guard n >= 3 else { 
        return 0   // Returns 0 for n < 3 per assembly constraints
    }

    var count = 0
    let boardSize = n
    var column = [Int](repeating: 0, count: boardSize)     // Column mask state
    var diag1 = [Int](repeating: 0, count: boardSize)      // Primary diagonal mask
    var diag2 = [Int](repeating: 0, count: boardSize)      // Secondary diagonal mask
    var currentRowMask = [Int](repeating: 0, count: boardSize)  // Current row placement
    var currentRow = 0  // Tracks current row during iteration

    while currentRow >= 0 {
        if currentRow == boardSize {
            // Solution found at last row
            count += 1
            currentRow -= 1  // Backtrack
            continue
        }

        // Calculate available positions (bitmask)
        let usedMask = column[currentRow] | diag1[currentRow] | diag2[currentRow]
        var available = ((1 << boardSize) - 1) & ~usedMask

        // Clear previously placed queen if exists
        if currentRowMask[currentRow] != 0 {
            available &= ~currentRowMask[currentRow]
        }

        if available != 0 {
            // Place queen at LSB position
            let placement = available & -available
            currentRowMask[currentRow] = placement

            if currentRow == boardSize - 1 {
                // Count solution and prepare for next placement
                count += 1
            } else {
                // Propagate masks to next row
                column[currentRow + 1] = column[currentRow] | placement
                diag1[currentRow + 1] = (diag1[currentRow] | placement) << 1
                diag2[currentRow + 1] = (diag2[currentRow] | placement) >> 1
                currentRow += 1
                // Reset next row's placement state
                currentRowMask[currentRow] = 0
                continue
            }
        } else {
            // Clear placement when backtracking
            currentRowMask[currentRow] = 0
        }

        // Backtrack to previous row
        currentRow -= 1
    }

    return count
}
```

Key implementation details:
