func isPartSum(divs: ArraySlice<Element>, sum: Element) -> Bool where Element: SignedInteger {
    // Base case: target sum achieved
    if sum == 0 {
        return true
    }

    // Base case: no elements remaining
    guard let last = divs.last else {
        return false
    }

    // Recursive cases
    if last > sum {
        // Skip element larger than remaining sum
        return isPartSum(divs: divs.dropLast(), sum: sum)
    }

    // Check both paths (with/without last element)
    return isPartSum(divs: divs.dropLast(), sum: sum) || 
           isPartSum(divs: divs.dropLast(), sum: sum - last)
}
```

