public func longestIncreasingSubsequence() -> [Element] {
  var startI = [Int](repeating: 0, count: count)
  var endI = [Int](repeating: 0, count: count + 1)
  var len = 0

  for i in 0..<count {
    var lo = 1
    var hi = len

    while lo <= hi {
      let mid = Int(ceil((Double(lo + hi)) / 2))

      if self[endI[mid]] <= self[i] {
        lo = mid + 1
      } else {
        hi = mid - 1
      }
    }

    startI[i] = endI[lo-1]
    endI[lo] = i

    if lo > len {
      len = lo
    }
  }

  var s = [Element]()
  var k = endI[len]

  for _ in 0..<len {
    s.append(self[k])
    k = startI[k]
  }

  return s.reversed()
}

