extension Array where Element: Comparable {
    func longestIncreasingSubsequence() -> [Element] {
        guard !isEmpty else { return [] }

        // dp stores indices of the smallest tail values for increasing subsequences
        var dp: [Int] = []
        // predecessor stores the previous index in the subsequence for each element
        var predecessor = Array(repeating: -1, count: count)

        for currentIndex in indices {
            // Binary search for insertion position in dp
            var low = 0
            var high = dp.count - 1

            while low <= high {
                let mid = (low + high + 1) / 2  // Ceiling division
                if self[dp[mid]] < self[currentIndex] {
                    low = mid + 1
                } else {
                    high = mid - 1
                }
            }

            // Update dp and predecessor arrays
            if low == dp.count {
                dp.append(currentIndex)
            } else {
                dp[low] = currentIndex
            }

            if low > 0 {
                predecessor[currentIndex] = dp[low - 1]
            }
        }

        // Reconstruct the subsequence in reverse order
        var current = dp.last!
        var result: [Element] = []

        for _ in 0..<dp.count {
            result.append(self[current])
            current = predecessor[current]
        }

        return result.reversed()
    }
}
```

