func powerset<T: Hashable>(from set: Set<T>) -> Set<Set<T>> {
    // Handle empty set case
    guard !set.isEmpty else {
        return [[]]
    }

    // Initialize result with the empty set
    var result: Set<Set<T>> = [[]]

    // Iterate through each element in the input set
    for element in set {
        // Preserve current state of result before modification
        let currentSubsets = result

        // For each existing subset, create new subset by adding current element
        for subset in currentSubsets {
            let newSubset = subset.union([element])
            result.insert(newSubset)
        }
    }

    return result
}
