func polyPrint<T: SignedNumeric & Comparable>(_ coefficients: [T]) {
    let degree = polyDegree(coefficients)

    // Handle zero polynomial
    if degree < 0 {
        print("0", terminator: "")
        return
    }

    var isFirstTerm = true
    var output = ""

    for exponent in stride(from: degree, through: 0, by: -1) {
        let coeff = coefficients[exponent]
        if coeff == 0 { continue }

        var term = ""
        let absCoeff: T

        // Sign handling
        if isFirstTerm {
            isFirstTerm = false
            if coeff < 0 {
                term += "-"
                absCoeff = -coeff
            } else {
                absCoeff = coeff
            }
        } else {
            if coeff < 0 {
                term += " - "
                absCoeff = -coeff
            } else {
                term += " + "
                absCoeff = coeff
            }
        }

        // Coefficient display (skip '1' unless constant term)
        if !(absCoeff == 1 && exponent != 0) {
            term += "\(absCoeff)"
        }

        // Variable and exponent display
        switch exponent {
        case 0: break  // No variable for constant term
        case 1: term += "x"
        default: term += "x^\(exponent)"
        }

        output += term
    }

    print(output, terminator: "")
}

